import csv
import io
import re


def parse_csv(raw_csv: str):
    csv.field_size_limit(max(csv.field_size_limit(), len(raw_csv)))
    records = list(csv.reader(io.StringIO(raw_csv, newline="")))

    if not records:
        return {"columns": [], "rows": []}

    header_count = 1
    while header_count < min(3, len(records)):
        row = records[header_count]
        if any(cell.strip() for cell in row[:3]) or not any(
            cell.strip() for cell in row
        ):
            break
        header_count += 1

    width = max(42, max(len(row) for row in records))
    headers = [
        row + [""] * (width - len(row))
        for row in records[:header_count]
    ]
    rows = [
        row + [""] * (width - len(row))
        for row in records[header_count:]
    ]

    def clean(value):
        return re.sub(r"\s+", " ", value).strip()

    columns = []
    used = set()
    parent = ""
    subheader = ""

    for index in range(width):
        top = clean(headers[0][index])
        if top:
            parent = top
            subheader = ""

        parts = [parent] if parent else []
        if header_count > 1:
            second = clean(headers[1][index])
            if second:
                subheader = second
            if subheader and subheader.casefold() not in {
                part.casefold() for part in parts
            }:
                parts.append(subheader)

        if header_count > 2:
            third = clean(headers[2][index])
            if third and third.casefold() not in {
                part.casefold() for part in parts
            }:
                parts.append(third)

        base = " - ".join(parts) or f"Column {index + 1}"
        name = base
        suffix = 2
        while name in used:
            name = f"{base} ({suffix})"
            suffix += 1
        used.add(name)
        columns.append(name)

    return {"columns": columns, "rows": rows}
